/* TOKI. No network, framework, account, or build service required to study. */
'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
const E=DATA.eras, L=E.flatMap(e=>e.lessons.map(l=>({...l,era:e.id})));
const EM=Object.fromEntries(E.map(e=>[e.id,e])), LM=Object.fromEntries(L.map(l=>[l.id,l]));
const lensNames=['World','Power','Daily life','Society','Language'];
const KEY='toki.history.v1';
const ICONS={
arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',
journey:'<path d="M5 19c0-5 14-3 14-9 0-3-5-3-5-6"/><circle cx="5" cy="19" r="2"/><path d="m11 7 3-4 4 2"/>',explore:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',dojo:'<path d="m12 3 2.7 5.6L21 9.5 16.5 14l1.1 6.2L12 17.3l-5.6 2.9L7.5 14 3 9.5l6.3-.9z"/>',passport:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M8 3v18M11 17h6"/><circle cx="14" cy="10" r="3"/>',
flame:'<path d="M12 3c1 4 6 5 6 11a6 6 0 0 1-12 0c0-3 2-5 3-6 0 3 1 4 2 4 2-1 2-5 1-9Z"/>',spark:'<path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8Z"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 13a5 5 0 0 1 3 4v3"/>',timeline:'<path d="M4 6h16M4 12h12M4 18h8"/><circle cx="8" cy="6" r="2"/><circle cx="13" cy="12" r="2"/><circle cx="6" cy="18" r="2"/>',words:'<path d="M3 5h12M9 3v2M5 5c0 5 3 8 8 10M13 5c-1 5-4 9-9 11M13 21l4-10 4 10M15 17h4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',compare:'<rect x="2" y="5" width="7" height="14" rx="1"/><rect x="15" y="5" width="7" height="14" rx="1"/><path d="M10 10h4m-4 4h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',leaf:'<path d="M20 3C8 2 1 8 5 16s16 2 15-13ZM5 21 16 9"/>',power:'<path d="m3 7 4 4 5-7 5 7 4-4-2 13H5z"/>',home:'<path d="m3 11 9-8 9 8M5 9v12h14V9M9 21v-7h6v7"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',external:'<path d="M14 3h7v7m0-7L11 13M10 3H3v18h18v-7"/>',flag:'<path d="M5 22V3c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>',cards:'<rect x="7" y="5" width="14" height="16" rx="2"/><path d="M17 2H4a2 2 0 0 0-2 2v13M10 10h8M10 14h6"/>',moon:'<path d="M20 14a9 9 0 0 1-11-11 9 9 0 1 0 11 11Z"/>'};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spark}</svg>`}
const lensIcon=l=>({'World':'explore','Power':'power','Daily life':'home','Society':'people','Language':'words'}[l]);
const fresh=()=>({version:1,xp:0,completed:{},questions:{},sessions:{},activeLesson:null,saved:[],notes:{},days:{},awards:{},scenarios:{},settings:{sound:false,large:false},started:Date.now()});
let state=fresh(), storageOK=true;
function cleanState(raw){
 if(!raw||raw.version!==1||typeof raw!=='object')throw Error('This is not a TOKI version 1 progress file.');
 const t=fresh(), num=(n,a,b)=>Number.isFinite(n)?clamp(n,a,b):a;
 t.xp=num(raw.xp,0,1000000);t.started=num(raw.started,0,Date.now());
 for(const l of L){
  const c=raw.completed?.[l.id];if(c&&typeof c==='object')t.completed[l.id]={best:num(c.best,0,2),at:num(c.at,0,Date.now()),attempts:num(c.attempts,1,100000)};
  if(typeof raw.notes?.[l.id]==='string')t.notes[l.id]=raw.notes[l.id].slice(0,4000);
  const s=raw.sessions?.[l.id];
  if(s&&Number.isInteger(s.step)&&s.step>=0&&s.step<=6){
   const ans=[null,null];if(Array.isArray(s.answers))for(let i=0;i<2;i++){const a=s.answers[i];if(a&&Number.isInteger(a.selected)&&a.selected>=0&&a.selected<3)ans[i]={selected:a.selected,correct:a.selected===0};}
   const ord=Array.isArray(s.orders)&&s.orders.length===2?s.orders.map(o=>Array.isArray(o)&&o.length===3&&new Set(o).size===3&&o.every(v=>[0,1,2].includes(v))?o:shuffle([0,1,2])):[shuffle([0,1,2]),shuffle([0,1,2])];
   let step=s.step;if(step>=5&&!ans[0])step=4;if(step>=6&&!ans[1])step=5;
   t.sessions[l.id]={step,answers:ans,orders:ord,xp:num(s.xp,0,35)};
  }
  for(const type of ['concept','term']){const id=l.id+':'+type,q=raw.questions?.[id];if(q&&typeof q==='object')t.questions[id]={correct:num(q.correct,0,100000),total:num(q.total,1,100000),streak:num(q.streak,0,100000),due:num(q.due,0,Date.now()+366*864e5),last:num(q.last,0,Date.now()),lastCorrect:q.lastCorrect===true};}
 }
 t.activeLesson=LM[raw.activeLesson]?raw.activeLesson:null;
 t.saved=Array.isArray(raw.saved)?[...new Set(raw.saved.filter(id=>LM[id]))]:[];
 for(const [k,v]of Object.entries(raw.days||{}))if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isFinite(v))t.days[k]=num(v,0,100000);
 for(const [k,v]of Object.entries(raw.awards||{}))if(/^[a-z0-9:_-]{1,100}$/.test(k)&&v===true&&!['__proto__','constructor','prototype'].includes(k))t.awards[k]=true;
 for(const sc of ACTIVITIES.scenarios){const s=raw.scenarios?.[sc.id];if(s&&Array.isArray(s.choices)&&s.choices.length<=3&&s.choices.every(v=>Number.isInteger(v)&&v>=0&&v<3))t.scenarios[sc.id]={choices:s.choices,ack:s.ack===true,finished:s.finished===true&&s.choices.length===3};}
 t.settings={sound:raw.settings?.sound===true,large:raw.settings?.large===true};return t;
}
try{const s=localStorage.getItem(KEY);if(s)state=cleanState(JSON.parse(s));localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}$('.storage-warning')?.classList.toggle('show',!storageOK)}
function localDay(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function dayOffset(n){const d=new Date();d.setDate(d.getDate()+n);return localDay(d)}
function activity(){const d=localDay();state.days[d]=(state.days[d]||0)+1;save()}
function streak(){let n=0,i=state.days[localDay()]?0:-1;while(state.days[dayOffset(i)]&&n<5000){n++;i--}return n}
function reward(key,xp){if(state.awards[key])return 0;state.awards[key]=true;state.xp+=xp;save();return xp}
function completeCount(e){return e.lessons.filter(l=>state.completed[l.id]).length}
const done=()=>Object.keys(state.completed).length;
function mastered(){return Object.values(state.questions).filter(q=>q.lastCorrect&&q.streak>=2).length}
function dueIds(){return Object.entries(state.questions).filter(([k,v])=>v.due<=Date.now()).sort((a,b)=>a[1].due-b[1].due).map(([k])=>k)}
function weakIds(){return Object.entries(state.questions).filter(([k,v])=>!v.lastCorrect).map(([k])=>k)}
function nextLesson(){return L.find(l=>!state.completed[l.id])||L[0]}
function getQ(id){const [lid,type]=id.split(':'),l=LM[lid];if(!l)return null;if(type==='concept')return {id,lid,era:l.era,lens:l.lens,title:l.question,options:l.options,why:l.why,refs:l.refs};
 const idx=L.findIndex(x=>x.id===lid),candidates=L.filter(x=>x.id!==lid&&x.term.meaning!==l.term.meaning),a=candidates[(idx*7)%candidates.length],b=candidates[(idx*7+13)%candidates.length];
 return {id,lid,era:l.era,lens:'Language',title:`In this history context, what does ${l.term.romaji} (${l.term.jp}) mean?`,options:[l.term.meaning,a.term.meaning,b.term.meaning],why:`${l.term.romaji}: ${l.term.meaning} These are modern readings of study vocabulary, not recordings of historical speech.`,refs:l.refs};}
function recordQ(id,correct){const q=state.questions[id]||{correct:0,total:0,streak:0,due:0,last:0,lastCorrect:false};const spaced=Date.now()-q.last>=20*3600000;q.total++;q.correct+=correct?1:0;q.streak=correct?(!q.lastCorrect?1:q.streak+(spaced?1:0)):0;q.lastCorrect=correct;q.last=Date.now();q.due=Date.now()+(correct?[1,3,7,14,30][Math.min(q.streak-1,4)]*864e5:10*60e3);state.questions[id]=q;save()}
let toastTimer;function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3400)}
let audio;function sound(ok=true){if(!state.settings.sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=ok?660:300;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.start();o.stop(audio.currentTime+.16)}catch(e){}}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const d=document.createElement('div');d.className='confetti';d.innerHTML=Array.from({length:24},(_,i)=>`<i style="left:${10+Math.random()*80}%;animation-delay:${Math.random()*.3}s;transform:rotate(${Math.random()*180}deg)"></i>`).join('');document.body.appendChild(d);setTimeout(()=>d.remove(),2200)}
function speak(text){if(!('speechSynthesis'in window)){toast('Speech is not supported by this browser.');return;}const voice=speechSynthesis.getVoices().find(v=>/^ja(-|_)/i.test(v.lang));if(!voice){toast('No Japanese voice is available on this device. The text and reading remain available.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.voice=voice;u.rate=.8;u.onerror=()=>toast('Audio could not play. Voice availability can depend on your device or connection.');speechSynthesis.speak(u);}
function refs(ids){return `<details class="source-details"><summary>${icon('book',15)} Evidence & further reading ${icon('chevron',12)}</summary><p>These selected sources support the chapter. The explanations and fictional learning scenes are original teaching material; no scene is a historical transcript.</p>${[...new Set(ids)].map(id=>{const s=DATA.sources[id];return s?`<a href="${esc(s[2])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} &middot; ${esc(s[1])} &#8599;</a>`:''}).join('')}</details>`}
function back(label='Back',target='journey'){return `<div class="backline"><div class="row"><button class="icon-btn" data-nav="${esc(target)}" aria-label="${esc(label)}">${icon('back')}</button><span>${esc(label)}</span></div><span class="offline-pill"><i class="offline-dot"></i>${storageOK?'Saved on this device':'Backup recommended'}</span></div>`}
function button(text,act,id='',cls=''){return `<button class="btn ${cls}" data-act="${act}"${id?` data-id="${esc(id)}"`:''}>${esc(text)}${icon('arrow',17)}</button>`}
function navButton(text,path,cls=''){return `<button class="btn ${cls}" data-nav="${esc(path)}">${esc(text)}${icon('arrow',17)}</button>`}
function landscape(){return `<svg class="hero-art" viewBox="0 0 400 390" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="grain" width="19" height="19" patternUnits="userSpaceOnUse"><circle cx="2" cy="3" r=".65" fill="#eeeac5" opacity=".14"/><circle cx="12" cy="13" r=".5" fill="#eeeac5" opacity=".1"/></pattern><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#214b3e"/><stop offset="1" stop-color="#365c43"/></linearGradient></defs><rect width="400" height="390" fill="url(#sky)"/><circle cx="321" cy="186" r="36" fill="#e9bb6c"/><circle cx="321" cy="186" r="44" fill="none" stroke="#edce94" opacity=".15"/><path d="M190 293 285 195 337 245 378 203 432 272V390H0V311Z" fill="#66836b"/><path d="m249 232 36-37 26 25-20-3-7 6-9-2Z" fill="#ccd2b3" opacity=".8"/><path d="M0 304Q63 225 139 280T289 269T449 281V390H0Z" fill="#80946e"/><path d="M-20 345Q73 253 175 317T410 314V400H0Z" fill="#476f50"/><path d="M0 373Q83 308 159 338T403 325V400H0" fill="#234936"/><path d="M212 287q-74 31-15 54t-46 58" stroke="#d4c391" stroke-width="7" fill="none" opacity=".65"/><g fill="#244b38"><path d="m66 276-15 37h30zM71 264l-13 30h26z"/><path d="M69 296h4v25h-4zM333 272l-16 38h32zM333 258l-13 30h26zM331 290h4v32h-4z"/></g><g stroke="#dbc9a0" fill="none" opacity=".65" stroke-width="1"><path d="m186 256 28-6M179 261l14-3M342 233l15-2"/></g><path d="m244 310 19-24 25 24z" fill="#d2b079"/><path d="m263 286 2 24h-17z" fill="#ac8050"/><rect width="400" height="390" fill="url(#grain)"/></svg>`}
function eraRow(e,i){const c=completeCount(e),isCurrent=nextLesson().era===e.id;return `<button class="era-row ${c===5?'complete':isCurrent?'current':''}" data-nav="era/${e.id}"><div class="era-medallion"><span class="jp" lang="ja">${esc(e.jp)}</span><small>${String(i+1).padStart(2,'0')}</small></div><div class="era-info"><div class="eyebrow">${esc(e.dates)}</div><h3>${esc(e.name)}</h3><small>${c===5?'Chapter explored':isCurrent?'Your next chapter':e.lessons.length+' missions  -  5 perspectives'}</small>${c>0?`<div class="progress-line"><i style="width:${c*20}%"></i></div>`:''}</div><span class="era-count">${c?c+'/5':icon('chevron',16)}</span></button>`}
function ring(n,max=3){const p=clamp(n/max,0,1);return `<div class="ring"><svg viewBox="0 0 44 44"><circle cx="22" cy="22" r="18" fill="none" stroke="#e4e8d8" stroke-width="3"/><circle cx="22" cy="22" r="18" fill="none" stroke="#456b40" stroke-width="3" stroke-dasharray="${p*113.1} 113.1" stroke-linecap="round"/></svg><span>${Math.min(n,max)}/${max}</span></div>`}
function journey(){const active=state.activeLesson&&state.sessions[state.activeLesson]?.step<6?LM[state.activeLesson]:null;const l=active||nextLesson(),e=EM[l.era],n=state.days[localDay()]||0;return `<div class="page-intro"><div class="eyebrow accent">YOUR HISTORY ADVENTURE</div><h1>A little time travel.<br>A whole new world.</h1><p>Japan, one story at a time.</p></div><section class="hero">${landscape()}<span class="hero-chip" lang="ja">${esc(e.jp.slice(0,2))}</span><div class="hero-top"><div class="eyebrow">CHAPTER ${String(E.indexOf(e)+1).padStart(2,'0')} / 18 &nbsp; &middot; &nbsp; ${esc(e.name)}</div><h2>${done()===0&&!active?'Before there<br>was Japan.':esc(e.tag)}</h2><p class="hero-sub">${done()===0&&!active?'Follow the first footprints.<br>Your journey starts long before<br>the first emperor.':esc(l.title)}</p></div><div class="hero-foot"><div class="hero-next">${icon('clock',13)} ${esc(e.dates)} &nbsp; &middot; &nbsp; 5 perspectives</div>${button(active?'Continue your story':done()===0?'Begin the journey':'Travel to the next story','start',l.id)}</div></section><div class="goal-card">${ring(n)}<div class="goal-text"><b>${n>=3?'A good day for discovery.':'A little history, every day.'}</b><p>${n>=3?'Daily goal reached. Curiosity has no limit.':'Complete 3 missions or games for your daily goal.'}</p></div>${icon(n>=3?'check':'leaf',23)}</div><div class="section-head"><h2>Take a side quest</h2><span class="eyebrow">PLAY TO LEARN</span></div><div class="quick-grid"><button class="quick-card" data-nav="scenarios"><span class="quick-icon">${icon('people',25)}</span><b>Live a day</b><small>Make the choices</small></button><button class="quick-card" data-act="new-timeline"><span class="quick-icon">${icon('timeline',25)}</span><b>Time shuffle</b><small>Find the order</small></button><button class="quick-card" data-act="new-match"><span class="quick-icon">${icon('words',25)}</span><b>Word match</b><small>Connect the dots</small></button></div><div class="section-head"><h2>Your path through time</h2><span class="eyebrow">${done()} / 90 MISSIONS</span></div><div class="progress-line"><i style="width:${done()/90*100}%"></i></div><div class="timeline-list mt">${E.map(eraRow).join('')}</div><div class="end-banner"><h3>One history. Many perspectives.</h3><p>Power, ordinary lives, social relationships, language, and the evidence that helps us understand them. Every chapter is open from the start.</p></div><p class="footer-note">A broad foundation, not the final word.<br>Researched through October 10, 2026.</p>`}
let searchText='',filter='All';
function explore(){return `<div class="page-intro"><div class="eyebrow accent">FOLLOW YOUR CURIOSITY</div><h1>There is more<br>than one way in.</h1><p>18 eras. 90 stories. Choose your own path.</p></div><div class="explore-tools"><button data-nav="compare">${icon('compare',18)} Compare eras</button><button data-nav="sources">${icon('book',18)} Source library</button></div><div class="search-wrap">${icon('search',20)}<input id="search" type="search" placeholder="Try samurai, rice, women, language..." value="${esc(searchText)}" aria-label="Search all lessons"></div><div class="chips" role="group" aria-label="Filter by perspective">${['All',...lensNames].map(n=>`<button class="chip ${filter===n?'active':''}" data-act="filter" data-id="${n}" aria-pressed="${filter===n}">${n}</button>`).join('')}</div><div id="search-results">${searchResults()}</div>`}
function searchResults(){if(!searchText&&filter==='All')return `<div class="eyebrow">ALL CHAPTERS &middot; ALWAYS OPEN</div><div class="timeline-list">${E.map(eraRow).join('')}</div>`;const q=searchText.toLowerCase().trim();const list=L.filter(l=>(filter==='All'||l.lens===filter)&&(!q||[l.title,EM[l.era].name,l.lens,l.term.jp,l.term.romaji,l.term.meaning,...l.pages].join(' ').toLowerCase().includes(q)));return `<div class="eyebrow" style="margin-bottom:12px">${list.length} ${list.length===1?'STORY':'STORIES'} FOUND</div><div class="search-results">${list.map(l=>`<button class="found-row" data-act="start" data-id="${l.id}"><span class="eyebrow">${esc(EM[l.era].name)} &middot; ${l.lens}</span><h3>${esc(l.title)}</h3><p>${esc(l.term.romaji)} &middot; ${state.completed[l.id]?'Completed':'Explore this mission'} ${state.saved.includes(l.id)?'&middot; Saved':''}</p></button>`).join('')||'<div class="empty"><h2>A different trail?</h2><p>Try a broader term or remove the perspective filter.</p></div>'}</div>`}
function eraPage(id){const e=EM[id];if(!e)return journey();const c=completeCount(e);return `${back('Your journey')}<section class="era-banner"><span class="era-jp" lang="ja">${esc(e.jp)}</span><div class="eyebrow accent">CHAPTER ${String(E.indexOf(e)+1).padStart(2,'0')} &middot; ${esc(e.dates)}</div><h1>${esc(e.name)}</h1><p>${esc(e.desc)}</p><div class="progress-line"><i style="width:${c*20}%"></i></div><div class="between small" style="margin-top:9px"><span>${c} of 5 missions explored</span><span>${c===5?'Stamp earned':5-c+' to your stamp'}</span></div></section>${e.sensitive?'<div class="note warm"><b>A serious chapter</b>Contains non-graphic discussion of war, colonial violence, sexual coercion, and civilian suffering. Study at your own pace. There are no conquest rewards or timers.</div>':''}<div class="section-head"><h2>Five ways to see it</h2><span class="eyebrow">STORY + PRACTICE</span></div><div class="stack">${e.lessons.map((l,i)=>`<button class="lesson-item" data-act="start" data-id="${l.id}"><span class="lesson-num">${state.completed[l.id]?icon('check',16):i+1}</span><span class="content"><span class="eyebrow">${l.lens}</span><h3>${esc(l.title)}</h3><small>${state.completed[l.id]?`Best recall ${state.completed[l.id].best}/2 &middot; Revisit`:state.sessions[l.id]?'In progress &middot; Resume':'3 reading cards &middot; 2 retrieval questions'}</small></span>${icon('chevron',16)}</button>`).join('')}</div><div class="section-head"><h2>The era at a glance</h2></div><div class="card"><span class="pill">${icon('explore',12)} ${esc(e.region)}</span><div class="lens-grid">${[['Power','power'],['Daily life','life'],['Language','voice']].map(([label,key])=>`<div class="lens-card"><h3>${icon(lensIcon(label),17)} ${label}</h3><p>${esc(e[key])}</p></div>`).join('')}</div></div><div class="note mt"><b>Period boundaries are tools, not walls.</b>Archaeological changes were regionally uneven. Some political periods overlap; founding dates and period labels can differ between historians.</div>${refs(e.refs)}`}
function startLesson(id,restart=false){if(!LM[id])return;if(restart||!state.sessions[id])state.sessions[id]={step:0,answers:[null,null],orders:[shuffle([0,1,2]),shuffle([0,1,2])],xp:0};state.activeLesson=id;save();go('lesson/'+id)}
function lesson(id){const l=LM[id];if(!l)return journey();if(!state.sessions[id])state.sessions[id]={step:0,answers:[null,null],orders:[shuffle([0,1,2]),shuffle([0,1,2])],xp:0};const s=state.sessions[id],e=EM[l.era],st=s.step;state.activeLesson=id;save();if(st===6)return lessonResult(l,s);
 const header=`<div class="lesson-top"><button class="icon-btn" data-nav="era/${e.id}" aria-label="Save and leave mission">${icon('close')}</button><div class="progress-line" role="progressbar" aria-label="Mission progress" aria-valuenow="${st}" aria-valuemin="0" aria-valuemax="6"><i style="width:${(st+1)/6*100}%"></i></div><span class="small">${st+1} / 6</span><button class="icon-btn ${state.saved.includes(id)?'active':''}" data-act="bookmark" data-id="${id}" aria-label="${state.saved.includes(id)?'Remove bookmark':'Bookmark mission'}" aria-pressed="${state.saved.includes(id)}">${icon('bookmark',19)}</button></div>`;
 const label=`<div class="lesson-lens"><span class="pill">${icon(lensIcon(l.lens),12)} ${l.lens}</span><span class="pill outline" style="margin-left:5px">${esc(e.name)}</span></div>`;
 if(st<3)return `${header}${label}<h1 class="lesson-title">${esc(l.title)}</h1>${st===0?`<div class="scene"><span class="eyebrow" style="display:block;margin-bottom:6px">IMAGINE THE SCENE</span>${esc(l.scene)}</div>`:''}<article class="reading-card"><div class="eyebrow">${['THE WORLD YOU ENTER','LOOK A LITTLE CLOSER','THE IDEA TO TAKE WITH YOU'][st]}</div><p>${esc(l.pages[st])}</p></article><div class="reading-controls"><div class="dots">${[0,1,2].map(i=>`<i class="${i===st?'on':''}"></i>`).join('')}</div>${st>0?`<button class="text-btn" data-act="prev-step" data-id="${id}">${icon('back',14)} Previous card</button>`:'<span class="micro">Read at your pace. No timer.</span>'}</div>${button(st===2?'Meet a word from this world':'Turn the page','next-step',id)}${refs(l.refs)}`;
 if(st===3)return `${header}${label}<h1 class="lesson-title">A word to carry<br>with you.</h1><div class="term-card"><span class="eyebrow">YOUR FIELD VOCABULARY</span><button class="icon-btn" data-act="speak-term" data-id="${id}" aria-label="Hear modern Japanese pronunciation">${icon('sound',18)}</button><div class="japanese" lang="ja">${esc(l.term.jp)}</div><div class="romaji">${esc(l.term.romaji)}</div><div class="meaning">${esc(l.term.meaning)}</div></div><p class="term-note">${E.indexOf(e)<5?'This is modern study vocabulary, not evidence of how people in this era spoke.':'The meaning belongs to its historical context. Audio uses a modern Japanese voice, not reconstructed period speech.'} Romanization omits macrons; long vowels still matter.</p>${button('Try it from memory','next-step',id)}<button class="text-btn mt" data-act="prev-step" data-id="${id}">${icon('back',14)} Read the last card again</button>${refs(l.refs)}`;
 const qi=st-4,q=getQ(id+':'+(qi===0?'concept':'term')),a=s.answers[qi];return `${header}<div class="eyebrow accent">RETRIEVE, DON\'T JUST RECOGNIZE &middot; ${qi+1}/2</div><h1 class="question">${esc(q.title)}</h1>${renderOptions(q,s.orders[qi],a,'lesson-answer',id)}${a?renderFeedback(q,a.correct)+button(qi===1?'Finish this mission':'One more connection','next-step',id):'<p class="micro mt">Choose the strongest answer. Mistakes become review cards, not penalties.</p>'}${a?refs(l.refs):''}`;
}
function renderOptions(q,order,a,action,id=''){return `<div class="options">${order.map((v,i)=>`<button class="option ${a?(v===0?'correct':v===a.selected?'wrong':''):''} ${a&&a.selected===v?'chosen':''}" data-act="${action}" data-id="${esc(id)}" data-val="${v}" ${a?'disabled':''}><span class="option-letter">${a&&v===0?icon('check',13):a&&v===a.selected?icon('close',13):'ABC'[i]}</span><span>${esc(q.options[v])}</span></button>`).join('')}</div>`}
function renderFeedback(q,correct){return `<div class="feedback ${correct?'':'wrong'}" role="status" tabindex="-1"><h3>${icon(correct?'check':'leaf',17)} ${correct?'A connection made.':'A useful thing to learn.'}</h3><p>${esc(q.why)}</p><small>${correct?'This question will return after a spacing interval.':'Added to focused review. You can practice it now in the Dojo.'}</small></div>`}
function lessonResult(l,s){const score=s.answers.filter(a=>a?.correct).length,e=EM[l.era],c=completeCount(e),next=L[L.indexOf(l)+1];return `${back('Back to '+e.name,'era/'+e.id)}<section class="result"><div class="result-emblem"><span class="jp" lang="ja">${esc(e.jp)}</span></div><div class="eyebrow accent">MISSION EXPLORED</div><h1>${score===2?'You made the<br>connections.':'The story stays.<br>Keep connecting.'}</h1><p>${esc(l.title)}<br>${c===5?'All five perspectives explored. Era stamp earned.':'Another perspective added to your journey.'}</p><div class="result-stats"><div><b>${score}/2</b><span>Recall this time</span></div><div><b>+${s.xp||0}</b><span>XP earned</span></div><div><b>${c}/5</b><span>Era missions</span></div></div></section>${score<2?'<div class="note"><b>Understanding grows through return visits.</b>The missed questions are in focused review. Completion tracks the stories you explored; memory strength tracks repeated successful retrieval.</div>':''}<label class="field-label" for="reflection">One thing worth remembering</label><textarea id="reflection" data-lesson="${l.id}" maxlength="4000" placeholder="What surprised you? What changed your view?">${esc(state.notes[l.id]||'')}</textarea><p class="micro" style="margin:7px 0 22px">Your note saves as you type, on this device.</p><div class="stack">${next?button('Continue to the next story','start',next.id):navButton('See your completed journey','passport')}${navButton('Return to this era','era/'+e.id,'secondary')}<button class="text-btn" data-act="restart" data-id="${l.id}">${icon('refresh',14)} Study this mission again</button></div>${refs(l.refs)}`}
let quiz=null,tgame=null,match=null,phrase=null,compareA='heian',compareB='edo';
function dojo(){const n=dueIds().length,w=weakIds().length,seen=Object.keys(state.questions).length;return `<div class="page-intro"><div class="eyebrow accent">THE MEMORY DOJO</div><h1>Make it stick.<br>Make it play.</h1><p>No lives to lose. Just connections to make.</p></div><section class="game-feature"><span class="watermark" lang="ja">&#23398;</span><div class="eyebrow">YOUR PERSONAL PRACTICE</div><h2>${n?n+' cards ready<br>for a return visit.':seen?'A return visit<br>changes everything.':'Your memory trail<br>starts with a story.'}</h2><p>${seen?`${n} due now &middot; ${w} to strengthen. Review adapts to your answers, then spaces the next visit.`:'Explore a mission first. Your answers will create a personal review deck.'}</p>${button(seen?'Start focused review':'Explore your first mission',seen?'review':'start',seen?'':nextLesson().id)}</section><div class="section-head"><h2>Choose your challenge</h2><span class="eyebrow">NO TIMER</span></div><div class="game-list">${gameRow('Live a day','Six imagined lives. Real historical tradeoffs.','people','scenarios','6 stories &middot; 18 decisions')}${gameRow('Time shuffle','Put four events in order, then uncover the story.','timeline','!new-timeline','29 historical anchors')}${gameRow('Word match','Pair Japanese study words with their meanings.','words','!new-match','90 contextual terms')}${gameRow('Mixed recall','Ten questions across eras and perspectives.','spark','!mixed','180 question prompts')}${gameRow('The phrase lab','Choose contemporary language for the situation.','sound','!new-phrase','12 everyday interactions')}</div><div class="note mt"><b>Completion is not the same as memory.</b>Review intervals expand after successful spaced retrieval. A missed answer returns after 10 minutes and is available immediately in focused practice. Repeat practice has no penalty.</div><p class="footer-note">Recognition questions build a foundation. Your notes, comparisons,<br>and explanations help take that knowledge further.</p>`}
function gameRow(title,text,symbol,path,tag){return `<button class="game-row" ${path.startsWith('!')?`data-act="${path.slice(1)}"`:`data-nav="${path}"`}><span class="game-symbol">${icon(symbol,24)}</span><div><h3>${title}</h3><p>${text}</p>${tag?`<small>${tag}</small>`:''}</div>${icon('chevron',16)}</button>`}
function startQuiz(mode){let ids;if(mode==='review'){const d=dueIds(),w=weakIds();ids=[...new Set([...d,...w])];if(!ids.length)ids=shuffle(Object.keys(state.questions));if(!ids.length){startLesson(nextLesson().id);return;}ids=ids.slice(0,10);}else ids=shuffle(L.flatMap(l=>[l.id+':concept',l.id+':term'])).slice(0,10);quiz={mode,ids,i:0,answers:[],orders:ids.map(()=>shuffle([0,1,2])),earned:0};go('review');}
function reviewPage(){if(!quiz)return `<div class="page-intro"><div class="eyebrow">FOCUSED PRACTICE</div><h1>Ready to reconnect?</h1><p>Your past answers are saved. Start a new review round.</p></div>${button('Start focused review','review')}${navButton('Back to the Dojo','dojo','secondary mt')}`;
 const {ids,i}=quiz;if(i>=ids.length){const score=quiz.answers.filter(a=>a.correct).length;return `${back('Memory Dojo','dojo')}<div class="result"><div class="result-emblem">${icon('leaf',48)}</div><div class="eyebrow accent">ROUND COMPLETE</div><h1>A stronger thread<br>through history.</h1><p>${score} of ${ids.length} connections retrieved. Every answer has a next review date.</p><div class="result-stats"><div><b>${score}/${ids.length}</b><span>Correct</span></div><div><b>+${quiz.earned}</b><span>XP earned</span></div><div><b>${dueIds().length}</b><span>Still due</span></div></div></div><div class="stack">${button('Another round','review')}${navButton('Return to the Dojo','dojo','secondary')}</div><div class="section-head"><h2>Keep these close</h2></div><div class="stack">${quiz.ids.filter((id,j)=>!quiz.answers[j]?.correct).map(id=>{const q=getQ(id);return `<button class="found-row" data-act="start" data-id="${q.lid}"><span class="eyebrow">${esc(EM[q.era].name)}</span><h3>${esc(LM[q.lid].title)}</h3><p>Revisit the explanation ${icon('arrow',12)}</p></button>`}).join('')||'<div class="note">All correct this round. Let some time pass before your next retrieval; spacing is part of the practice.</div>'}</div>`;}
 const q=getQ(ids[i]),a=quiz.answers[i];return `${back('Memory Dojo','dojo')}<div class="between"><span class="eyebrow accent">${quiz.mode==='mixed'?'MIXED RECALL':'FOCUSED REVIEW'}</span><span class="small">${i+1} / ${ids.length}</span></div><div class="progress-line" style="margin:13px 0 20px"><i style="width:${i/ids.length*100}%"></i></div><span class="pill">${esc(EM[q.era].name)} &middot; ${q.lens}</span><h1 class="question">${esc(q.title)}</h1>${renderOptions(q,quiz.orders[i],a,'quiz-answer')}${a?renderFeedback(q,a.correct)+button(i===ids.length-1?'Finish the round':'Next connection','quiz-next'):''}${a?refs(q.refs):'<p class="micro mt">Focus on the reasoning, not just the label.</p>'}`}
function newTimeline(){tgame={ids:shuffle(ACTIVITIES.timeline.map((e,i)=>i)).slice(0,4),selected:[],checked:false,hints:false,earned:0};go('timeline')}
function timelinePage(){if(!tgame)newTimeline();const t=tgame,events=ACTIVITIES.timeline,ordered=[...t.ids].sort((a,b)=>events[a][0]-events[b][0]);if(t.checked){const score=t.selected.filter((v,i)=>v===ordered[i]).length;return `${back('Memory Dojo','dojo')}<div class="page-intro"><span class="eyebrow accent">THE THREAD THROUGH TIME</span><h1>${score===4?'Right time.<br>Right place.':'See how the<br>story unfolds.'}</h1><p>${score}/4 events placed correctly${t.hints?' with dates revealed':''}. +${t.earned} XP this round.</p></div><div class="stack">${ordered.map((id,i)=>{const e=events[id];return `<article class="card"><div class="eyebrow accent">${e[0]} &middot; ${esc(EM[e[3]].name)}</div><h3 style="margin-top:8px">${esc(e[1])}</h3><p>${esc(e[2])}</p>${refs([e[4]])}</article>`}).join('')}</div><div class="stack mt">${button('Shuffle another four','new-timeline')}${navButton('Return to the Dojo','dojo','secondary')}</div>`;}
 return `${back('Memory Dojo','dojo')}<div class="page-intro"><span class="eyebrow accent">TIME SHUFFLE</span><h1>First this.<br>Then what?</h1><p>Tap the events from earliest to latest. Dates appear after you commit, unless you ask for a hint.</p></div><div class="timeline-slots">${[0,1,2,3].map(i=>`<div class="time-slot ${t.selected[i]!==undefined?'filled':''}">${t.selected[i]!==undefined?esc(events[t.selected[i]][1]):i===0?'Earliest event':i===3?'Latest event':'Your next event'}</div>`).join('')}</div><div class="between" style="margin-bottom:12px"><button class="text-btn" data-act="timeline-undo" ${t.selected.length?'':'disabled'}>${icon('back',14)} Undo last</button><button class="text-btn" data-act="timeline-hint">${icon('info',14)} ${t.hints?'Dates revealed':'Reveal dates'}</button></div><div class="stack">${t.ids.map(id=>`<button class="event-option" data-act="timeline-select" data-id="${id}" ${t.selected.includes(id)?'disabled':''}>${t.hints?`<span class="event-date">${events[id][0]}</span>`:icon('cards',18)}<span>${esc(events[id][1])}</span></button>`).join('')}</div><div class="mt"><button class="btn" data-act="timeline-check" ${t.selected.length===4?'':'disabled'}>Check the timeline ${icon('arrow',17)}</button></div>`}
function newMatch(){const seen=L.filter(l=>state.completed[l.id]),pool=seen.length>=4?seen:L;const ids=shuffle(pool.map(l=>l.id)).slice(0,4);match={ids,left:shuffle(ids),right:shuffle(ids),selL:null,selR:null,matched:[],misses:0,busy:false,earned:0,done:false};go('match')}
function matchPage(){if(!match)newMatch();const m=match;if(m.done)return `${back('Memory Dojo','dojo')}<div class="result"><div class="result-emblem">${icon('words',45)}</div><span class="eyebrow accent">FOUR CONNECTIONS MADE</span><h1>Words open<br>worlds.</h1><p>+${m.earned} XP &middot; ${m.misses} mismatched ${m.misses===1?'pair':'pairs'} along the way.<br>Every attempt helps you notice the difference.</p></div><div class="stack">${m.ids.map(id=>`<button class="found-row" data-act="start" data-id="${id}"><span class="eyebrow">${esc(EM[LM[id].era].name)}</span><h3><span lang="ja">${esc(LM[id].term.jp)}</span> &middot; ${esc(LM[id].term.romaji)}</h3><p>${esc(LM[id].term.meaning)}</p></button>`).join('')}${button('Match another four','new-match')}${navButton('Return to the Dojo','dojo','secondary')}</div>`;
 return `${back('Memory Dojo','dojo')}<div class="page-intro"><span class="eyebrow accent">WORD MATCH &middot; ${m.matched.length}/4</span><h1>A word.<br>A world of meaning.</h1><p>Tap a word, then its meaning. Once you have explored four missions, this game draws from your completed stories.</p></div><div class="match-grid">${['left','right'].map(side=>`<div class="match-col">${m[side].map(id=>{const term=LM[id].term,sel=(side==='left'?m.selL:m.selR)===id,matched=m.matched.includes(id);return `<button class="match-tile ${sel?'selected':''} ${matched?'matched':''} ${m.busy&&sel?'miss':''}" data-act="match-select" data-id="${id}" data-side="${side}" ${matched||m.busy?'disabled':''} aria-pressed="${sel}">${side==='left'?`<span class="jp" lang="ja">${esc(term.jp)}</span><span>${esc(term.romaji)}</span>`:esc(term.meaning)}${matched?icon('check',15):''}</button>`}).join('')}</div>`).join('')}</div><p class="micro">These are modern readings of historical study terms. Matching is recognition practice; it does not count as spaced recall mastery.</p>`}
function scenariosPage(){return `${back('Memory Dojo','dojo')}<div class="page-intro"><span class="eyebrow accent">IN SOMEONE ELSE\'S SHOES</span><h1>History was<br>someone's Tuesday.</h1><p>Six imagined lives. Choices with consequences. Discover the institutions behind an ordinary day.</p></div><div class="game-list">${ACTIVITIES.scenarios.map(s=>gameRow(s.title,`${EM[s.era].name} &middot; ${s.role}`,'people','scenario/'+s.id,state.scenarios[s.id]?.finished?'Story explored &middot; Play again':state.scenarios[s.id]?.choices.length?'Your choices are saved &middot; Resume':'3 decisions &middot; Resources, relationships, insight')).join('')}</div><div class="note mt"><b>Historical context. Fictional situations.</b>Characters, dialogue, choices, and resource values are teaching devices, not documented lives or numerical models of past societies. No choice can change the historical record.</div>`}
function scenarioTotals(sc,s){let a=[3,3,3];s.choices.forEach((v,i)=>{a=a.map((n,j)=>clamp(n+sc.steps[i].choices[v].delta[j],0,9))});return a}
function resources(v){return `<div class="scenario-stat">${['Resources','Relationships','Insight'].map((label,i)=>`<div><small>${label}</small><b>${v[i]}<span class="small"> / 9</span></b><div class="progress-line"><i style="width:${v[i]/9*100}%"></i></div></div>`).join('')}</div>`}
function scenarioPage(id){const sc=ACTIVITIES.scenarios.find(s=>s.id===id);if(!sc)return scenariosPage();const s=state.scenarios[id]||(state.scenarios[id]={choices:[],ack:true,finished:false}),v=scenarioTotals(sc,s);if(s.finished){const high=v.indexOf(Math.max(...v)),names=['The practical planner','The relationship builder','The careful observer'],insights=['You protected material capacity. Consider whose cooperation and knowledge made those resources usable.','You invested in relationships. Consider who supplied the material resources that made cooperation sustainable.','You invested in understanding. Consider what resources and relationships are needed to act on that knowledge.'];return `${back('All decision stories','scenarios')}<div class="result"><div class="result-emblem">${icon(['home','people','explore'][high],45)}</div><div class="eyebrow accent">YOUR PATH THROUGH THE STORY</div><h1>${names[high]}</h1><p>${insights[high]}</p></div>${resources(v)}<div class="note"><b>There is no perfect historical score.</b>The meters represent tradeoffs inside this fictional exercise. They do not measure the value of real people or establish what actually happened.</div><div class="section-head"><h2>The choices you made</h2></div><div class="stack">${s.choices.map((n,i)=>`<article class="card"><span class="eyebrow">DECISION ${i+1}</span><h3 style="margin-top:7px">${esc(sc.steps[i].choices[n].label)}</h3><p>${esc(sc.steps[i].choices[n].result)}</p></article>`).join('')}${navButton('Explore the '+EM[sc.era].name+' chapter','era/'+sc.era)}<button class="btn secondary" data-act="scenario-restart" data-id="${id}">Try a different path ${icon('refresh',17)}</button></div>${refs(sc.refs)}`;}
 const answered=s.ack===false,index=answered?s.choices.length-1:s.choices.length,step=sc.steps[index],choice=answered?step.choices[s.choices[index]]:null;
 return `${back('All decision stories','scenarios')}<span class="pill">${esc(EM[sc.era].name)} &middot; Decision ${index+1}/3</span><h1 class="lesson-title" style="margin-top:16px">${esc(sc.title)}</h1>${index===0?`<div class="scene">${esc(sc.intro)}</div>`:''}${resources(v)}<div class="eyebrow accent">${esc(sc.role)}</div><h2 class="question">${esc(step.title)}</h2><p style="font-size:14px;margin-bottom:19px">${esc(step.text)} ${v[0]<=2?esc(step.low):v[1]>=6?'Your earlier investment in relationships gives you a stronger network to draw on.':v[2]>=6?'Your earlier attention to context helps you notice what each option leaves out.':''}</p><div class="options">${step.choices.map((c,i)=>`<button class="option ${answered&&s.choices[index]===i?'correct chosen':''}" data-act="scenario-choose" data-id="${id}" data-val="${i}" ${answered?'disabled':''}><span class="option-letter">${answered&&s.choices[index]===i?icon('check',13):'ABC'[i]}</span><span>${esc(c.label)}</span></button>`).join('')}</div>${choice?`<div class="feedback" role="status"><h3>Your choice changes the day.</h3><p>${esc(choice.result)}</p><div class="delta">${choice.delta.map((n,i)=>n?`<span>${n>0?'+':''}${n} ${['resources','relationships','insight'][i]}</span>`:'').join('')}</div></div>${button(index===2?'Reflect on your path':'See what happens next','scenario-next',id)}`:'<p class="micro mt">Choose a priority, not a supposedly perfect answer. All options reveal a tradeoff.</p>'}${refs(sc.refs)}`}
function newPhrase(){phrase={i:0,order:shuffle([0,1,2]),answers:[],earned:0};go('phrases')}
function phrasePage(){if(!phrase)newPhrase();const p=phrase;if(p.i>=ACTIVITIES.phrases.length)return `${back('Memory Dojo','dojo')}<div class="result"><div class="result-emblem">${icon('sound',45)}</div><span class="eyebrow accent">PHRASE LAB COMPLETE</span><h1>Context comes<br>before translation.</h1><p>${p.answers.filter(a=>a.correct).length}/12 situations matched. +${p.earned} XP.<br>These are contemporary examples, not period dialogue.</p></div>${button('Practice the situations again','new-phrase')}${navButton('Return to the Dojo','dojo','secondary mt')}`;
 const f=ACTIVITIES.phrases[p.i],a=p.answers[p.i],opts=[f,ACTIVITIES.phrases[(p.i+4)%12],ACTIVITIES.phrases[(p.i+7)%12]],q={options:opts.map(v=>v[0]+' / '+v[1])};return `${back('Memory Dojo','dojo')}<div class="between"><span class="eyebrow accent">THE PHRASE LAB &middot; MODERN JAPANESE</span><span class="phrase-counter">${p.i+1}/12</span></div><h1 class="question">${esc(f[3])}</h1><p class="small" style="margin-bottom:20px">Which expression fits this situation?</p>${renderOptions(q,p.order,a,'phrase-answer')}${a?`<div class="feedback ${a.correct?'':'wrong'}" role="status"><h3>${a.correct?'That fits the situation.':'A new expression to carry.'}</h3><p><b>${esc(f[1])}</b> &mdash; ${esc(f[2])}.</p><p style="margin-top:10px">${esc(f[4])}</p><button class="text-btn mt" data-act="speak-phrase" data-id="${p.i}">${icon('sound',17)} Hear a modern Japanese voice</button></div>${button(p.i===11?'Finish the phrase lab':'Try the next situation','phrase-next')}`:''}<div class="note mt">Speech requires an available Japanese device voice. These phrases are not a complete language course; register and meaning depend on context.</div>`}
function passport(){const ranks=[['First footprints',0],['Curious traveler',150],['Story seeker',500],['Context keeper',1200],['Time archivist',2500],['Lifelong learner',4000]],r=[...ranks].reverse().find(r=>state.xp>=r[1]),next=ranks[ranks.indexOf(r)+1],pct=next?(state.xp-r[1])/(next[1]-r[1])*100:100,stamps=E.filter(e=>completeCount(e)===5).length;return `<div class="page-intro"><div class="eyebrow accent">YOUR TIME TRAVEL PASSPORT</div><h1>The places your<br>curiosity has been.</h1></div><section class="passport"><span class="jp-watermark" lang="ja">&#26053;</span><div class="eyebrow">TOKI EXPLORER &middot; LEVEL ${ranks.indexOf(r)+1}</div><h1>${r[0]}</h1><p>${state.xp.toLocaleString()} XP &middot; Every perspective counts.</p><div class="progress-line"><i style="width:${pct}%"></i></div><div class="between"><span>${next?next[1]-state.xp+' XP to '+next[0]:'The journey is a practice, not a finish line.'}</span>${icon('spark',14)}</div></section><div class="stats-grid"><div class="stat-box"><b>${done()}</b><span>of 90 missions</span></div><div class="stat-box"><b>${streak()}</b><span>day ${streak()===1?'streak':'streak'}</span></div><div class="stat-box"><b>${stamps}</b><span>of 18 stamps</span></div></div><div class="card"><div class="between"><h3>Your last seven days</h3><span class="small">A little, often.</span></div><div class="week">${Array.from({length:7},(_,i)=>{const day=dayOffset(i-6),d=new Date(day+'T12:00:00');return `<div class="day ${state.days[day]?'done':''}"><span>${d.toLocaleDateString('en',{weekday:'narrow'})}</span><i>${state.days[day]?icon('check',14):d.getDate()}</i></div>`}).join('')}</div></div><div class="section-head"><h2>Memory, not just miles</h2><span class="eyebrow">${mastered()} / 180 STRENGTHENED</span></div><div class="card">${lensNames.map(lens=>{const ids=L.flatMap(l=>[...(l.lens===lens?[l.id+':concept']:[]),...(lens==='Language'?[l.id+':term']:[])]),tested=ids.filter(id=>state.questions[id]),strong=tested.filter(id=>state.questions[id].lastCorrect&&state.questions[id].streak>=2),percent=tested.length?Math.round(strong.length/tested.length*100):0;return `<div class="skill-row"><span>${lens}</span><div class="progress-line"><i style="width:${percent}%"></i></div><small>${tested.length?percent+'%':'New'}</small></div>`}).join('')}<p class="micro">Strength = two or more correct retrievals separated by at least 20 hours. Percentages use questions you have attempted, not all unstudied content. A reading completion alone never grants memory strength.</p></div><div class="section-head"><h2>Your era stamps</h2><span class="eyebrow">EXPLORE ALL 5 TO EARN</span></div><div class="stamps">${E.map(e=>`<button class="stamp ${completeCount(e)===5?'earned':''}" data-nav="era/${e.id}" aria-label="${esc(e.name)}: ${completeCount(e)} of 5 missions"><span class="jp" lang="ja">${esc(e.jp)}</span><span>${esc(e.name)}</span><small>${completeCount(e)===5?'EXPLORED':completeCount(e)+' / 5'}</small></button>`).join('')}</div><div class="section-head"><h2>Your field notebook</h2><button class="text-btn" data-nav="notebook">Open ${icon('arrow',14)}</button></div><div class="goal-card">${icon('bookmark',24)}<div class="goal-text"><b>${state.saved.length} saved ${state.saved.length===1?'mission':'missions'}</b><p>${Object.values(state.notes).filter(Boolean).length} personal notes &middot; Private on this device.</p></div></div><div class="section-head"><h2>Make it yours</h2></div><div class="settings-list"><button class="setting" data-act="setting" data-id="large" role="switch" aria-checked="${state.settings.large}"><div>Larger reading text<p>More room for the words.</p></div><span class="switch ${state.settings.large?'on':''}"></span></button><button class="setting" data-act="setting" data-id="sound" role="switch" aria-checked="${state.settings.sound}"><div>Gentle game sounds<p>Off by default. No background music.</p></div><span class="switch ${state.settings.sound?'on':''}"></span></button><button class="setting" data-act="export"><div>Back up your progress<p>Export a JSON file. Keep it somewhere safe.</p></div>${icon('download',19)}</button><button class="setting" data-act="import"><div>Restore a backup<p>Replaces progress in this browser after confirmation.</p></div>${icon('upload',19)}</button><button class="setting" data-nav="about"><div>About TOKI & iPhone setup<p>Offline use, privacy, and learning design.</p></div>${icon('info',19)}</button><button class="setting" data-nav="sources"><div>Source library<p>${Object.keys(DATA.sources).length} references and further readings.</p></div>${icon('book',19)}</button><button class="setting" data-act="reset"><div style="color:var(--orange)">Reset progress<p>Deletes this browser's saved journey.</p></div>${icon('refresh',19)}</button></div><p class="footer-note">Progress belongs to this browser and this site address.<br>No login, tracking, or cloud synchronization.<br>Back up before clearing browser data or changing devices.</p>`}
function notebook(){const ids=L.filter(l=>state.saved.includes(l.id)||state.notes[l.id]);return `${back('Your passport','passport')}<div class="page-intro"><div class="eyebrow accent">THE FIELD NOTEBOOK</div><h1>Keep what<br>changed your mind.</h1><p>Bookmarked missions and your own reflections.</p></div><div class="bookmark-list">${ids.map(l=>`<article class="card"><div class="between"><span class="eyebrow">${esc(EM[l.era].name)} &middot; ${l.lens}</span><button class="icon-btn ${state.saved.includes(l.id)?'active':''}" data-act="bookmark" data-id="${l.id}" aria-label="Toggle bookmark" aria-pressed="${state.saved.includes(l.id)}">${icon('bookmark',17)}</button></div><h3>${esc(l.title)}</h3>${state.notes[l.id]?`<p class="note-preview">${esc(state.notes[l.id])}</p>`:''}<button class="text-btn mt" data-act="start" data-id="${l.id}">Revisit the mission ${icon('arrow',14)}</button></article>`).join('')||`<div class="empty">${icon('book',35)}<h2>Your next discovery goes here.</h2><p>Bookmark a mission while reading, or write a reflection after finishing it.</p>${navButton('Find a story','explore')}</div>`}</div>`}
function sourcePage(){return `${back('Explore','explore')}<div class="page-intro"><div class="eyebrow accent">THE EVIDENCE BEHIND THE STORIES</div><h1>Curiosity deserves<br>a paper trail.</h1><p>Selected museum, archive, academic, and official sources. External readings need an internet connection.</p></div><div class="note"><b>How to use these sources</b>Period labels and chronologies sometimes differ. Official records are primary evidence of institutions and statements, not automatically complete or neutral accounts. Museum interpretations can also be revised. Early dates are approximate; the contemporary snapshot ends October 10, 2026.</div><div class="mt">${Object.entries(DATA.sources).map(([id,s])=>`<a class="source-row" href="${esc(s[2])}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${esc(s[0])}</span><b>${esc(s[1])} &#8599;</b><span>${esc(new URL(s[2]).hostname)}</span></a>`).join('')}</div><p class="footer-note">Original teaching text, not quotations from these sources.<br>Illustrations and situations are schematic, not archaeological reconstructions.</p>`}
function comparePage(){return `${back('Explore','explore')}<div class="page-intro"><div class="eyebrow accent">THE LONG VIEW</div><h1>Same question.<br>Different worlds.</h1><p>Compare institutions and ordinary life, not just dates.</p></div><div class="compare-select">${[['compare-a',compareA,'FIRST ERA'],['compare-b',compareB,'SECOND ERA']].map(([id,val,label])=>`<div><label class="select-label" for="${id}">${label}</label><select id="${id}">${E.map(e=>`<option value="${e.id}" ${val===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div>`).join('')}</div>${[['Power','power'],['Daily life','life'],['Language & expression','voice']].map(([title,key])=>`<div class="section-head"><h2>${title}</h2></div><div class="comparison">${[compareA,compareB].map(id=>`<div><h3>${esc(EM[id].name)}</h3><p>${esc(EM[id][key])}</p></div>`).join('')}</div>`).join('')}<div class="note mt"><b>Try explaining it without the screen.</b>Who could make decisions? How were obligations enforced? Whose daily work sustained the system? Name one similarity and one difference.</div><div class="stack mt">${[compareA,compareB].map(id=>navButton('Explore '+EM[id].name,'era/'+id,'secondary')).join('')}</div>${refs([...EM[compareA].refs,...EM[compareB].refs])}`}
function about(){return `${back('Your passport','passport')}<div class="page-intro"><div class="eyebrow accent">MEET TOKI</div><h1>A pocket-sized<br>journey through time.</h1><p>Designed for curiosity, not cramming.</p></div><div class="stack"><article class="card"><h3>What is included</h3><p>18 era chapters, 90 missions, 270 reading cards, 180 retrieval prompts, 90 study terms, six three-decision stories, timeline games, word matching, and 12 contemporary phrase situations.</p><p>This is a broad chronological and thematic foundation, not an exhaustive history or a complete Japanese-language course. Each era deserves further study.</p></article><article class="card"><h3>Add TOKI to your iPhone</h3><p>Publish the app folder at an HTTPS website, then open that address in Safari. Open the Safari sharing controls, then choose Add to Home Screen. Enable Open as Web App when shown, and tap Add. Launch it from that icon for the standalone app experience.</p><p>After a successful online load, the service worker caches the app for offline study on supported browsers. External sources and some speech voices still need connectivity. An HTML file viewed in the iPhone Files preview is not the same as a hosted web app.</p><p id="offline-status" class="small">${location.protocol==='file:'?'Standalone file mode: the lessons are embedded; Home Screen installation needs the hosted folder.':('serviceWorker'in navigator&&navigator.serviceWorker.controller)?'Offline app cache is active for this browser.':'Offline installation is not yet confirmed. Load from HTTPS or localhost and reopen after caching.'}</p></article><article class="card"><h3>Your progress, honestly</h3><p>Lessons, answers, review schedules, bookmarks, notes, daily activity, and decision-story choices save in this browser\'s local storage. No data is sent to a server. There is no account or automatic cross-device sync.</p><p>Clearing website data, changing browser or site address, private browsing, or device loss can remove access to that progress. Export a backup from your Passport. Imported backups replace this browser\'s current progress only after confirmation.</p></article><article class="card"><h3>How memory practice works</h3><p>A correct first retrieval is scheduled for one day later. Successful retrievals at least 20 hours apart advance through 3, 7, 14, and 30-day intervals. A wrong answer resets the interval to 10 minutes and becomes immediately available in focused practice.</p><p>XP recognizes activity, not historical expertise. First mission completions earn 25 XP plus 5 per correct answer; completed missions do not award XP again. Decision stories award 20 XP once. Other game modes award their completion bonus once per local day. Repetition remains available without limits.</p></article><article class="card"><h3>Respect the evidence</h3><p>Earliest dates and routes are uncertain, period boundaries overlap, and neither modern borders nor modern Japanese can be projected unchanged into prehistory. Language audio is a device-generated modern reading. Romanization omits macrons for accessibility; long vowels still matter.</p><p>Imagined scenes and meter values make social tradeoffs visible but are not recovered conversations or empirical models. War and colonial violence are discussed without graphic imagery or conquest mechanics.</p></article><article class="card"><h3>Built to be approachable</h3><p>Tap controls work without dragging or swiping. There are no timers or lost lives. Larger reading text is available in Passport. Reduced-motion preferences are respected. Speech and gentle sounds are optional.</p></article></div><div class="note mt"><b>Content snapshot: October 10, 2026</b>Current-era facts are explicitly dated. This app does not fetch live news or silently update political officeholders or statistics.</div>${navButton('Explore the source library','sources','secondary mt')}`}
function routeParts(){try{return decodeURIComponent(location.hash.slice(1)||'journey').split('/')}catch(e){return ['journey']}}
function go(path){if(location.hash==='#'+path)render(true);else location.hash=path;}
function render(scroll=false){const [r,id]=routeParts();let html;try{html=({journey,explore,dojo,passport,notebook,sources:sourcePage,compare:comparePage,about,scenarios:scenariosPage,review:reviewPage,timeline:timelinePage,match:matchPage,phrases:phrasePage}[r]||(()=>r==='era'?eraPage(id):r==='lesson'?lesson(id):r==='scenario'?scenarioPage(id):journey()))();}catch(e){console.error(e);html=`${back()}<div class="empty"><h2>This trail needs a reset.</h2><p>Your saved progress has not been deleted. Return to the journey or export a backup from Passport.</p>${navButton('Return to the journey','journey')}</div>`;}
 $('#app').innerHTML=html;document.body.classList.toggle('large-text',state.settings.large);document.body.classList.toggle('is-lesson',r==='lesson');const tab=['era','lesson'].includes(r)?'journey':['sources','compare'].includes(r)?'explore':['scenarios','scenario','review','timeline','match','phrases'].includes(r)?'dojo':['notebook','about'].includes(r)?'passport':r;
 document.querySelectorAll('.nav button').forEach(b=>{b.classList.toggle('active',b.dataset.nav===tab);if(b.dataset.nav===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});updateHeader();$('.storage-warning').classList.toggle('show',!storageOK);if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#app').focus({preventScroll:true});}document.title='TOKI  -  '+({journey:'Your journey',dojo:'Memory Dojo',passport:'Your passport',explore:'Explore',lesson:LM[id]?.title,era:EM[id]?.name}[r]||'Japanese history');}
function updateHeader(){$('#header-stats').innerHTML=`<span class="header-stat" aria-label="${streak()} day streak">${icon('flame',17)} ${streak()}</span><span class="header-stat xp" aria-label="${state.xp} experience points">${icon('spark',16)} ${state.xp}</span>`}
function modal(title,text,confirmText,fn){const d=$('#confirm-dialog');$('#dialog-title').textContent=title;$('#dialog-text').textContent=text;$('#dialog-confirm').textContent=confirmText;d._confirm=fn;d.showModal();}
$('#dialog-cancel').addEventListener('click',()=>$('#confirm-dialog').close());
$('#dialog-confirm').addEventListener('click',()=>{const d=$('#confirm-dialog'),f=d._confirm;d.close();d._confirm=null;f?.()});
function finishLesson(id){const s=state.sessions[id];if(!s||s.step>=6||!s.answers[0]||!s.answers[1])return;const score=s.answers.filter(a=>a.correct).length,old=state.completed[id];s.xp=old?0:reward('mission:'+id,25+5*score);state.completed[id]={best:Math.max(old?.best||0,score),at:Date.now(),attempts:(old?.attempts||0)+1};s.step=6;activity();save();render(true);sound(true);if(!EM[LM[id].era].sensitive)celebrate();}
function exportProgress(){try{const payload={...state,exportedAt:new Date().toISOString(),app:'TOKI Japanese History'},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='toki-progress-'+localDay()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);toast('Backup file created. Keep it outside this browser.')}catch(e){toast('The backup could not be created in this browser.')}}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000){toast('That file is too large. TOKI backups must be under 2 MB.');return;}try{const raw=JSON.parse(await file.text()),clean=cleanState(raw);modal('Replace this journey?',`The backup contains ${Object.keys(clean.completed).length} completed missions and ${clean.xp} XP. Current local progress will be replaced. Export a backup first to keep both.`,'Restore backup',()=>{state=clean;save();go('passport');toast('Your backup has been restored.');});}catch(err){toast('Not a valid TOKI progress backup. Nothing was changed.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){searchText=e.target.value;$('#search-results').innerHTML=searchResults();}if(e.target.id==='reflection'&&LM[e.target.dataset.lesson]){state.notes[e.target.dataset.lesson]=e.target.value.slice(0,4000);save();}});
document.addEventListener('change',e=>{if(e.target.id==='compare-a'&&EM[e.target.value]){compareA=e.target.value;render()}if(e.target.id==='compare-b'&&EM[e.target.value]){compareB=e.target.value;render()}});
function focusFeedback(){requestAnimationFrame(()=>{const f=$('.feedback');if(f){f.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});f.focus?.({preventScroll:true});}})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-nav],[data-act]');if(!b||b.disabled)return;if(b.dataset.nav){go(b.dataset.nav);return;}const a=b.dataset.act,id=b.dataset.id,val=Number(b.dataset.val);try{switch(a){
case 'start':startLesson(id);break;
case 'restart':startLesson(id,true);break;
case 'bookmark':if(!LM[id])break;state.saved=state.saved.includes(id)?state.saved.filter(v=>v!==id):[...state.saved,id];save();render();toast(state.saved.includes(id)?'Mission added to your field notebook.':'Bookmark removed. Your note is still saved.');break;
case 'filter':filter=id;render();$('#search')?.focus({preventScroll:true});break;
case 'prev-step':{const s=state.sessions[id];if(s&&s.step>0&&s.step<=3){s.step--;save();render(true)}break;}
case 'next-step':{const s=state.sessions[id];if(!s||s.step===6)break;if(s.step===5){finishLesson(id);break;}if(s.step===4&&!s.answers[0])break;s.step++;save();render(true);break;}
case 'lesson-answer':{const s=state.sessions[id];if(!s||s.step<4||s.step>5||![0,1,2].includes(val))break;const qi=s.step-4;if(s.answers[qi])break;s.answers[qi]={selected:val,correct:val===0};recordQ(id+':'+(qi===0?'concept':'term'),val===0);save();sound(val===0);render();focusFeedback();break;}
case 'speak-term':if(LM[id])speak(LM[id].term.jp);break;
case 'speak-phrase':if(ACTIVITIES.phrases[Number(id)])speak(ACTIVITIES.phrases[Number(id)][0]);break;
case 'review':startQuiz('review');break;
case 'mixed':startQuiz('mixed');break;
case 'quiz-answer':if(quiz&&quiz.i<quiz.ids.length&&!quiz.answers[quiz.i]&&[0,1,2].includes(val)){quiz.answers[quiz.i]={selected:val,correct:val===0};recordQ(quiz.ids[quiz.i],val===0);sound(val===0);render();focusFeedback();}break;
case 'quiz-next':if(quiz&&quiz.answers[quiz.i]){quiz.i++;if(quiz.i===quiz.ids.length){quiz.earned=reward('quiz:'+quiz.mode+':'+localDay(),15);activity();}render(true);}break;
case 'new-timeline':newTimeline();break;
case 'timeline-select':if(tgame&&!tgame.checked&&tgame.ids.includes(Number(id))&&!tgame.selected.includes(Number(id))&&tgame.selected.length<4){tgame.selected.push(Number(id));sound();render();}break;
case 'timeline-undo':if(tgame&&!tgame.checked){tgame.selected.pop();render()}break;
case 'timeline-hint':if(tgame){tgame.hints=true;render()}break;
case 'timeline-check':if(tgame&&!tgame.checked&&tgame.selected.length===4){tgame.checked=true;tgame.earned=reward('timeline:'+localDay(),15);activity();render(true);sound();}break;
case 'new-match':newMatch();break;
case 'match-select':{if(!match||match.done||match.busy||match.matched.includes(id)||!match.ids.includes(id))break;const m=match,side=b.dataset.side;if(side==='left')m.selL=m.selL===id?null:id;else m.selR=m.selR===id?null:id;if(m.selL&&m.selR){if(m.selL===m.selR){m.matched.push(m.selL);m.selL=m.selR=null;sound();if(m.matched.length===4){m.done=true;m.earned=reward('match:'+localDay(),12);activity();render(true);celebrate();break;}toast('A connection made.');}else{m.misses++;m.busy=true;sound(false);toast('Not this pair. Look at the meaning and try again.');setTimeout(()=>{m.busy=false;m.selL=m.selR=null;if(routeParts()[0]==='match')render()},850)}}render();break;}
case 'scenario-choose':{const sc=ACTIVITIES.scenarios.find(x=>x.id===id),s=state.scenarios[id];if(!sc||!s||s.ack===false||s.finished||s.choices.length>=3||![0,1,2].includes(val))break;s.choices.push(val);s.ack=false;save();render();focusFeedback();break;}
case 'scenario-next':{const s=state.scenarios[id];if(!s||s.ack!==false||s.finished)break;s.ack=true;if(s.choices.length===3){s.finished=true;const xp=reward('scenario:'+id,20);activity();toast(`Story explored. +${xp} XP.`)}save();render(true);break;}
case 'scenario-restart':state.scenarios[id]={choices:[],ack:true,finished:false};save();render(true);break;
case 'new-phrase':newPhrase();break;
case 'phrase-answer':if(phrase&&phrase.i<12&&!phrase.answers[phrase.i]&&[0,1,2].includes(val)){phrase.answers[phrase.i]={selected:val,correct:val===0};sound(val===0);render();focusFeedback();}break;
case 'phrase-next':if(phrase&&phrase.answers[phrase.i]){phrase.i++;phrase.order=shuffle([0,1,2]);if(phrase.i===12){phrase.earned=reward('phrase:'+localDay(),15);activity();}render(true);}break;
case 'setting':if(['sound','large'].includes(id)){state.settings[id]=!state.settings[id];save();render();if(id==='sound'&&state.settings.sound)sound();}break;
case 'export':exportProgress();break;
case 'import':$('#import-file').click();break;
case 'reset':modal('Start a new journey?','This deletes local missions, notes, bookmarks, and review history. Export a progress backup first to keep your current journey.','Delete local progress',()=>{state=fresh();save();go('journey');toast('A new journey is ready.');});break;
}}catch(err){console.error(err);toast('That action could not finish. Your saved progress has not been erased.')}});
window.addEventListener('hashchange',()=>render(true));
window.addEventListener('pagehide',save);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=cleanState(JSON.parse(e.newValue));render();toast('Progress updated from another tab.')}catch(err){}}});
if('speechSynthesis'in window)speechSynthesis.getVoices();
if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{if(routeParts()[0]==='about')render()}).catch(()=>{});
render();
